window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-05f07fcab5f938a6"]={"versions": [{"id": "FIG-05f07fcab5f938a6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-basiertes Prozessdiagramm) zur Darstellung eines methodischen Arbeitsschritts im Entwurfsprozess. Es veranschaulicht die Einbettung der Aktivität „Define Alias Names“ in den Gesamtablauf zur Verwaltung und Zuordnung alternativer Bezeichner für AUTOSAR-Modellelemente (beispielsweise im System- oder Software-Komponenten-Kontext).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Methodological Activity)</strong>: <code>Define Alias Names</code> (dargestellt als Pfeilsymbol/Prozessschritt).\n</li><li><strong>Eingangs-Artefakte (Input Work Products)</strong>:\n<ul class=\"fig-list\"><li><code>System Description</code> (Briefumschlag-Symbol mit Bindungsmarkierung/Teilmodell-Charakter, Multiplizität <code>0..1</code>, Beziehungsstereotyp <code>«input»</code>).\n</li><li>Zweites Eingangs-Artefakt am unteren Rand (abgeschnittene Beschriftung <code>Deliver / Delivered ... Atomic Software Component ...</code>, Briefumschlag-Symbol, Multiplizität <code>0..1</code>, Beziehungsstereotyp <code>«input»</code>).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt (Output Work Product)</strong>:\n<ul class=\"fig-list\"><li><code>Alias Name Set</code> (Dokumentsymbol mit Zeilenstruktur, Multiplizität <code>1</code>, Beziehungsstereotyp <code>«output»</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define Alias Names</code> nimmt optional eine <code>System Description</code> (Kardinalität <code>0..1</code>) sowie optional ein Software-Komponenten-Beschreibungsartefakt (Kardinalität <code>0..1</code>) entgegen. Basierend auf diesen Eingabemodellen definiert der Arbeitsschritt alternative Bezeichner (Aliase) für System- bzw. Software-Elemente und erzeugt deterministisch genau ein geschlossenes Artefakt vom Typ <code>Alias Name Set</code> (Kardinalität <code>1</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Spezifikation für AUTOSAR-Autorenwerkzeuge und -Modellierungsplattformen: Werkzeuge, die diese Aktivität implementieren, müssen das Anlegen von Alias-Definitionen ermöglichen, selbst wenn nur Teilmengen der Eingangsartefakte (System Description oder SWC-Beschreibung) vorliegen. Das erzeugte <code>Alias Name Set</code> muss dem AUTOSAR-Metamodell für Alias-Zuordnungen entsprechen und verbindlich als singuläres Ausgangsartefakt exportiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f61126b51e50b97f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-basiertes Prozessdiagramm) zur Darstellung eines methodischen Arbeitsschritts im Entwurfsprozess. Es veranschaulicht die Einbettung der Aktivität „Define Alias Names“ in den Gesamtablauf zur Verwaltung und Zuordnung alternativer Bezeichner für AUTOSAR-Modellelemente (beispielsweise im System- oder Software-Komponenten-Kontext).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Methodological Activity)</strong>: <code>Define Alias Names</code> (dargestellt als Pfeilsymbol/Prozessschritt).\n</li><li><strong>Eingangs-Artefakte (Input Work Products)</strong>:\n<ul class=\"fig-list\"><li><code>System Description</code> (Briefumschlag-Symbol mit Bindungsmarkierung/Teilmodell-Charakter, Multiplizität <code>0..1</code>, Beziehungsstereotyp <code>«input»</code>).\n</li><li>Zweites Eingangs-Artefakt am unteren Rand (abgeschnittene Beschriftung <code>Deliver / Delivered ... Atomic Software Component ...</code>, Briefumschlag-Symbol, Multiplizität <code>0..1</code>, Beziehungsstereotyp <code>«input»</code>).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt (Output Work Product)</strong>:\n<ul class=\"fig-list\"><li><code>Alias Name Set</code> (Dokumentsymbol mit Zeilenstruktur, Multiplizität <code>1</code>, Beziehungsstereotyp <code>«output»</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define Alias Names</code> nimmt optional eine <code>System Description</code> (Kardinalität <code>0..1</code>) sowie optional ein Software-Komponenten-Beschreibungsartefakt (Kardinalität <code>0..1</code>) entgegen. Basierend auf diesen Eingabemodellen definiert der Arbeitsschritt alternative Bezeichner (Aliase) für System- bzw. Software-Elemente und erzeugt deterministisch genau ein geschlossenes Artefakt vom Typ <code>Alias Name Set</code> (Kardinalität <code>1</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Spezifikation für AUTOSAR-Autorenwerkzeuge und -Modellierungsplattformen: Werkzeuge, die diese Aktivität implementieren, müssen das Anlegen von Alias-Definitionen ermöglichen, selbst wenn nur Teilmengen der Eingangsartefakte (System Description oder SWC-Beschreibung) vorliegen. Das erzeugte <code>Alias Name Set</code> muss dem AUTOSAR-Metamodell für Alias-Zuordnungen entsprechen und verbindlich als singuläres Ausgangsartefakt exportiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-05f07fcab5f938a6", "to": "FIG-f61126b51e50b97f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
